# RGB-derived: docs/fill_pen_holder/applied_values.json (rgb_derived_values).
"""RGB updates generated by --run-geometry-fitting.

Evidence: docs/fill_pen_holder/geometry_fit.json
Perception and manipulation use RGB, camera calibration, proprioception and SAM3.
"""
import json
import math
import numpy as np
from PIL import Image, ImageDraw

# Horizontal support datum used for the per-kind dimension offsets.
RGB_GEOMETRY_EVIDENCE = 'docs/fill_pen_holder/'
TABLE_Z = 0.765149899
LOG = []


def cam(robo, name='cam_head'):
    m = robo.camera_meta(name)
    return np.asarray(m['intrinsic_matrix'], float), np.asarray(m['extrinsic_matrix'], float)


def pixel_ray(K, E, rc):
    """World origin and unit direction of the ray through pixel (row, col)."""
    r, c = float(rc[0]), float(rc[1])
    d = E[:3, :3] @ np.array([(c - K[0, 2]) / K[0, 0], -(r - K[1, 2]) / K[1, 1], -1.0])
    return E[:3, 3].copy(), d / np.linalg.norm(d)


def ray_at_z(K, E, rc, z):
    o, d = pixel_ray(K, E, rc)
    return o + (z - o[2]) / d[2] * d


def project(K, E, pts):
    """World points -> (row, col) pixels."""
    P = np.atleast_2d(np.asarray(pts, float))
    pc = (P - E[:3, 3]) @ E[:3, :3]
    col = K[0, 2] + K[0, 0] * pc[:, 0] / -pc[:, 2]
    row = K[1, 2] - K[1, 1] * pc[:, 1] / -pc[:, 2]
    return np.c_[row, col]


def mask_of(seg, shape=(480, 640)):
    """Rasterize a Segment's outlines into a boolean mask."""
    im = Image.new('L', (shape[1], shape[0]), 0)
    dr = ImageDraw.Draw(im)
    for outline in seg.contours_rc or ():
        pts = [(int(c), int(r)) for r, c in outline]
        if len(pts) >= 3:
            dr.polygon(pts, fill=255)
    return np.asarray(im) > 0


def carve_holes(filled, area_px, rgb):
    """Remove enclosed background from a mask rasterized from outer outlines.

    ``robo.segment`` returns outer outlines and the true mask area. When the
    filled outline is larger than that area, the object encloses background
    (the table seen through a headband). The enclosed pixels that look most
    like the background just outside the outline are removed, up to the
    missing area.
    """
    import cv2
    extra = int(filled.sum()) - int(area_px)
    if area_px <= 0 or extra < 0.06 * filled.sum():
        return filled
    f = filled.astype(np.uint8)
    ring = (cv2.dilate(f, np.ones((15, 15), np.uint8)) > 0) & ~(cv2.dilate(f, np.ones((5, 5), np.uint8)) > 0)
    if ring.sum() < 50:
        return filled
    lab = cv2.cvtColor(np.ascontiguousarray(np.asarray(rgb)[:, :, :3]), cv2.COLOR_RGB2LAB).astype(np.float32)
    bg = lab[ring]
    mu, sd = bg.mean(axis=0), bg.std(axis=0) + 4.0
    inner = (cv2.erode(f, np.ones((3, 3), np.uint8)) > 0)
    d = np.full(filled.shape, np.inf, np.float32)
    d[inner] = np.sqrt((((lab[inner] - mu) / sd) ** 2).sum(axis=1))
    order = np.sort(d[inner])
    cut = order[min(len(order) - 1, extra)]
    hole = (d <= cut).astype(np.uint8)
    hole = cv2.morphologyEx(hole, cv2.MORPH_OPEN, np.ones((3, 3), np.uint8))
    n, labels, stats, _ = cv2.connectedComponentsWithStats(hole)
    keep = np.zeros_like(hole)
    for i in range(1, n):
        if stats[i, cv2.CC_STAT_AREA] >= max(40, 0.15 * extra):
            keep[labels == i] = 1
    return filled & ~(keep > 0)


def segment(robo, prompt, camera='cam_head', min_score=0.2):
    s = robo.segment(prompt, camera, min_score, include_contours=True)
    if not s.found:
        return None
    filled = mask_of(s)
    mask = carve_holes(filled, s.area_px, robo.image(camera))
    return dict(prompt=prompt, camera=camera, score=s.score, box=s.box, centroid=s.centroid,
                area=s.area_px, mask=mask, filled=int(filled.sum()), seg=s)


def overlay(robo, camera='cam_head', masks=(), points=(), lines=(), scale=2):
    """RGB overlay for review: mask outlines, world points/lines projected."""
    K, E = cam(robo, camera)
    im = Image.fromarray(np.asarray(robo.image(camera))).convert('RGB')
    dr = ImageDraw.Draw(im)
    cols = [(255, 0, 0), (0, 255, 0), (0, 160, 255), (255, 255, 0), (255, 0, 255), (0, 255, 255)]
    for i, m in enumerate(masks):
        if m is None:
            continue
        for outline in m['seg'].contours_rc or ():
            pts = [(int(c), int(r)) for r, c in outline]
            if len(pts) >= 3:
                dr.line(pts + [pts[0]], fill=cols[i % len(cols)], width=1)
    for i, p in enumerate(points):
        r, c = project(K, E, p)[0]
        dr.ellipse([c - 3, r - 3, c + 3, r + 3], outline=cols[i % len(cols)], width=2)
    for i, (a, b) in enumerate(lines):
        (r0, c0), (r1, c1) = project(K, E, [a, b])
        dr.line([(c0, r0), (c1, r1)], fill=cols[i % len(cols)], width=2)
    return im.resize((im.width * scale, im.height * scale))


def _rx(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[1.0, 0.0, 0.0], [0.0, c, -s], [0.0, s, c]])


def _ry(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, 0.0, s], [0.0, 1.0, 0.0], [-s, 0.0, c]])


def _rz(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, -s, 0.0], [s, c, 0.0], [0.0, 0.0, 1.0]])


def orientation(pitch, yaw, roll):
    """Gripper rotation for (pitch, yaw, roll) in degrees: Rz(90 + yaw) Ry(pitch) Rx(roll)."""
    return _rz(math.radians(90.0 + yaw)) @ _ry(math.radians(pitch)) @ _rx(math.radians(roll))


def angles(rot):
    """(pitch, yaw, roll) in degrees of a gripper rotation (not within a degree of vertical)."""
    point = rot[:, 0]
    pitch = math.degrees(math.asin(max(-1.0, min(1.0, -point[2]))))
    yaw = math.degrees(math.atan2(point[1], point[0])) - 90.0
    rest = orientation(pitch, yaw, 0.0).T @ rot
    roll = math.degrees(math.atan2(rest[2, 1], rest[1, 1]))
    wrap = lambda d: (d + 180.0) % 360.0 - 180.0
    return pitch, wrap(yaw), wrap(roll)


def used(robo):
    return int(robo.action_count())


def go(robo, arm, xyz, pitch=None, yaw=None, roll=None, path='line', gripper=0, label=''):
    """One move with a compact reply appended to LOG."""
    before = used(robo)
    m = robo.move_to([float(v) for v in xyz], arm=arm, gripper=gripper, pitch=pitch, yaw=yaw, roll=roll, path=path)
    rec = dict(label=label, arm=arm, reached=bool(m.reached), blocked=bool(getattr(m, 'blocked', False)),
               dist=float(getattr(m, 'dist_to_target_m', float('nan'))), note=getattr(m, 'note', None),
               ik_error=getattr(m, 'ik_error', None), actions=used(robo) - before, at=used(robo))
    LOG.append(rec)
    return rec


def approach(robo, arm, xyz, opening=None, label='', **kw):
    """Move an EMPTY hand to a pose with its fingers closed, then open it.

    With an open empty gripper the arm may take the pose turned half a turn
    about its pointing direction, which swaps the fingers and puts the wrist
    camera on the other side. A closed hand is taken exactly as asked.
    ``opening`` None leaves the hand closed; 1.0 opens fully.
    """
    rec = go(robo, arm, xyz, gripper=robo.CLOSE, label=label, **kw)
    if opening is not None and rec['reached']:
        before = used(robo)
        if opening >= 0.999:
            robo.set_gripper(arm, robo.OPEN)
        else:
            robo.set_gripper(arm, robo.OPEN, opening=opening)
        rec = dict(rec, actions=rec['actions'] + used(robo) - before, opened=opening)
    return rec


def glide(robo, arm, xyz, step_m=0.015, label='', **kw):
    """Straight move in short steps, one action each: no swing, low acceleration."""
    start = np.asarray(robo.state().arm(arm).tcp_pos, float)
    goal = np.asarray(xyz, float)
    n = max(1, int(math.ceil(np.linalg.norm(goal - start) / step_m)))
    before = used(robo)
    rec = None
    for k in range(1, n + 1):
        rec = go(robo, arm, start + (goal - start) * k / n, path='line', label=label, **kw)
        if not rec['reached'] and rec.get('ik_error'):
            break
    rec = dict(rec, actions=used(robo) - before, steps=n)
    return rec


def sheet(images, cols=4, size=(320, 240)):
    """Contact sheet of PIL/array images."""
    ims = [Image.fromarray(np.asarray(i)).convert('RGB').resize(size) for i in images]
    rows = (len(ims) + cols - 1) // cols
    out = Image.new('RGB', (cols * size[0], rows * size[1]))
    for i, im in enumerate(ims):
        out.paste(im, ((i % cols) * size[0], (i // cols) * size[1]))
    return out


def min_area_rect(points):
    """Minimum-area rectangle of 2D points: centre, (long, short), long-axis angle (rad), corners."""
    pts = np.asarray(points, float)
    P = sorted(map(tuple, np.unique(np.round(pts, 5), axis=0)))
    def half(seq):
        h = []
        for p in seq:
            while len(h) >= 2 and ((h[-1][0]-h[-2][0])*(p[1]-h[-2][1]) - (h[-1][1]-h[-2][1])*(p[0]-h[-2][0])) <= 0:
                h.pop()
            h.append(p)
        return h[:-1]
    hull = np.asarray(half(P) + half(P[::-1]))
    best = None
    for i in range(len(hull)):
        e = hull[(i + 1) % len(hull)] - hull[i]
        n = np.linalg.norm(e)
        if n < 1e-9:
            continue
        u = e / n
        v = np.array([-u[1], u[0]])
        a, b = hull @ u, hull @ v
        area = (a.max() - a.min()) * (b.max() - b.min())
        if best is None or area < best[0]:
            best = (area, u, v, a.min(), a.max(), b.min(), b.max())
    _, u, v, a0, a1, b0, b1 = best
    centre = u * (a0 + a1) / 2 + v * (b0 + b1) / 2
    la, lb = a1 - a0, b1 - b0
    corners = np.array([u*a0+v*b0, u*a1+v*b0, u*a1+v*b1, u*a0+v*b1])
    if la >= lb:
        long_dir, dims = u, (la, lb)
    else:
        long_dir, dims = v, (lb, la)
    ang = math.atan2(long_dir[1], long_dir[0])
    ang = (ang + math.pi / 2) % math.pi - math.pi / 2
    return dict(centre=centre, dims=dims, angle=ang, corners=corners)


def brief(d, drop=('mask', 'replies', 'corners', 'R', 'seg')):
    """Compact printable copy of a result dict."""
    out = {}
    for k, v in d.items():
        if k in drop:
            continue
        if isinstance(v, np.ndarray):
            v = np.round(v, 4).tolist()
        elif isinstance(v, tuple):
            v = tuple(round(float(x), 4) if isinstance(x, (float, np.floating)) else x for x in v)
        elif isinstance(v, dict):
            v = brief(v, drop)
        out[k] = v
    return out


# Fit based on RGB in geometry-fitting mode
HOLDER_HEIGHT = 0.120
HOLDER_OUTER_R = 0.0398
HOLDER_FLOOR = 0.7765 - TABLE_Z
HOLDER_INNER_FLAT = 0.0586 / 2.0  # Inner apothem, not full opening width.
RGB_TOOL_DIMS = {'purple_marker': {'length': 0.152, 'width': 0.0285, 'thick': 0.023}, 'blue_marker': {'length': 0.141, 'width': 0.03, 'thick': 0.022}, 'white_pen': {'length': 0.145, 'width': 0.015, 'thick': 0.012}, 'yellow_black_pen': {'length': 0.187, 'width': 0.016, 'thick': 0.014}}
# Unweighted class means of the per-kind RGB medians.
FALLBACK_DIMS = {'marker': {'length': 0.1465, 'width': 0.02925, 'thick': 0.0225}, 'pen': {'length': 0.166, 'width': 0.0155, 'thick': 0.013}}


DIMS = {}


def dims(model):
    """Length, width (seen from above when lying) and thickness of a tool, metres: median of this episode's head-view
    measurements of uncut blobs, or available RGB_TOOL_DIMS defaults.
    Tools without a default require a whole-tool measurement in this episode."""
    seen = DIMS.get(model)
    if not seen:
        if model in RGB_TOOL_DIMS:
            return dict(RGB_TOOL_DIMS[model], measured=0)
        raise ValueError(f'{model} needs an uncut RGB size measurement; survey or relook with the whole tool visible.')
    a = np.median(np.asarray(seen, float), axis=0)
    return dict(length=float(a[0]), width=float(a[1]), thick=float(a[2]), measured=len(seen))


def rays_at_z(K, E, rows, cols, z):
    """World (x, y) where the rays through many pixels (row, col arrays) meet the plane at height z."""
    d = np.c_[(np.asarray(cols, float) - K[0, 2]) / K[0, 0], -(np.asarray(rows, float) - K[1, 2]) / K[1, 1], -np.ones(len(rows))] @ E[:3, :3].T
    o = E[:3, 3]
    return o[:2] + ((z - o[2]) / d[:, 2])[:, None] * d[:, :2]


def colour_classes(rgb):
    """Per-pixel colour classes that separate the writing tools from the wooden table."""
    import cv2
    hsv = cv2.cvtColor(np.ascontiguousarray(np.asarray(rgb)[:, :, :3]), cv2.COLOR_RGB2HSV)
    h, s, v = hsv[:, :, 0].astype(int), hsv[:, :, 1].astype(int), hsv[:, :, 2].astype(int)
    white = (s < 28) & (v > 195)
    blue = (h >= 85) & (h <= 105) & (s >= 18) & (v > 170)
    purple = (h >= 122) & (h <= 165) & (s >= 60) & (v > 40)
    dark = (v < 52) | ((s < 40) & (v < 120))
    yellow = (h >= 16) & (h <= 34) & (s >= 70) & (v > 205)
    return dict(white=white & ~blue, blue=blue, purple=purple, dark=dark, yellow=yellow)


def table_region(K, E, shape=(480, 640), x=(-0.47, 0.08), y=(-0.31, 0.22)):
    """Image mask of the part of the table where the writing tools are searched for."""
    import cv2
    corners = [(x[0], y[0], TABLE_Z), (x[1], y[0], TABLE_Z), (x[1], y[1], TABLE_Z), (x[0], y[1], TABLE_Z)]
    rc = project(K, E, corners)
    m = np.zeros(shape, np.uint8)
    cv2.fillPoly(m, [np.round(rc[:, ::-1]).astype(np.int32)], 1)
    return m > 0


def classify_item(frac):
    """Model name from the colour make-up of a blob; None when the blob mixes the colours of two tools."""
    if frac['purple'] > 0.22:
        return 'purple_marker' if frac['blue'] + frac['yellow'] < 0.12 else None
    if frac['blue'] > 0.45:
        return 'blue_marker' if frac['dark'] + frac['yellow'] + frac['purple'] < 0.12 else None
    if frac['dark'] > 0.35 and frac['yellow'] > 0.06:
        return 'yellow_black_pen' if frac['white'] + frac['blue'] + frac['purple'] < 0.10 else None
    if frac['dark'] > 0.45:
        return 'black_pencil' if frac['blue'] + frac['purple'] < 0.10 and frac['white'] < 0.22 else None
    if frac['white'] > 0.5:
        return 'white_pen' if frac['dark'] + frac['blue'] + frac['purple'] + frac['yellow'] < 0.12 else None
    return None


RESIDUE = []


def find_items(rgb, K, E, exclude=None, area=None):
    """Writing tools lying on the table: one record per elongated coloured blob.

    Each record has the model name, the blob's two axis endpoints and centre on
    the table (world), its measured length and width, and the blob mask.
    ``exclude`` is an optional image mask of pixels to ignore (robot arms, holder).
    """
    import cv2
    cls = colour_classes(rgb)
    fg = cls['white'] | cls['blue'] | cls['purple'] | cls['dark'] | cls['yellow']
    region = table_region(K, E, fg.shape) if area is None else table_region(K, E, fg.shape, x=area[0], y=area[1])
    if exclude is not None:
        region = region & ~exclude
    fg &= region
    outside = cv2.dilate((~region).astype(np.uint8), np.ones((5, 5), np.uint8)) > 0
    f = cv2.morphologyEx(fg.astype(np.uint8), cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8))
    n, labels, stats, cent = cv2.connectedComponentsWithStats(f)
    items = []
    RESIDUE[:] = []
    for i in range(1, n):
        area = stats[i, cv2.CC_STAT_AREA]
        if area < 60 or area > 4500:
            if area > 4500 and area < 20000:
                RESIDUE.append(dict(area=int(area), centre=ray_at_z(K, E, cent[i][::-1], TABLE_Z + 0.01)[:2]))
            continue
        mask = labels == i
        rows, cols = np.nonzero(mask)
        frac = {k: float((cls[k] & mask).sum()) / area for k in cls}
        model = classify_item(frac)
        if model is None:
            if area >= 150:
                RESIDUE.append(dict(area=int(area), centre=ray_at_z(K, E, cent[i][::-1], TABLE_Z + 0.01)[:2]))
            continue
        size = measure_blob(K, E, rows, cols)
        z, axis, mean, lo, hi = size['z'], size['axis'], size['mean'], size['lo'], size['hi']
        length, width, thick = size['length'], size['width'], size['thick']
        if not (length > width):
            if area >= 150:
                RESIDUE.append(dict(area=int(area), centre=ray_at_z(K, E, cent[i][::-1], TABLE_Z + 0.01)[:2]))
            continue
        centre = mean + axis * (lo + hi) / 2
        length, width = view_corrected(K, E, model, np.array([centre[0], centre[1], z]), axis, length, width, thick)
        items.append(dict(model=model, centre=np.array([centre[0], centre[1], z]), axis=np.array([axis[0], axis[1], 0.0]),
                          a=np.array([*(centre + axis * (hi - lo) / 2), z]), b=np.array([*(centre - axis * (hi - lo) / 2), z]),
                          length=length, width=width, thick=RGB_TOOL_DIMS.get(model, {}).get('thick', thick),
                          blob_thick=thick, area=int(area), frac=frac, mask=mask,
                          cut=bool((mask & outside).sum() > 3)))
    return items


def measure_blob(K, E, rows, cols):
    """Axis, length, width and thickness of a lying round tool from its blob pixels in one calibrated view.

    The pixels are cast onto a plane 1 cm above the table. The width is the 3rd-97th percentile spread across the
    axis. Seen obliquely, a lying round body shows a silhouette wider than itself by 1 / sin(e), where e is the
    elevation of the viewing ray in the plane square to the body's axis; the thickness is the width times sin(e).
    The pixels are then cast again at half that thickness above the table, and the length is the 0.5th-99.5th
    percentile extent along the axis plus the size of one pixel there.
    """
    z = TABLE_Z + 0.010
    thick = None
    for _ in range(2):
        pts = rays_at_z(K, E, rows, cols, z)
        mean = pts.mean(axis=0)
        w, vec = np.linalg.eigh(np.cov((pts - mean).T))
        axis, across = vec[:, 1], vec[:, 0]
        u = (pts - mean) @ across
        width = float(np.percentile(u, 97) - np.percentile(u, 3))
        ray = np.array([mean[0], mean[1], z]) - E[:3, 3]
        ray = ray / np.linalg.norm(ray)
        sin_e = math.sin(math.atan2(abs(ray[2]), abs(ray[0] * across[0] + ray[1] * across[1])))
        thick = width * sin_e
        if abs(TABLE_Z + thick / 2 - z) < 0.001:
            break
        z = TABLE_Z + thick / 2
    t = (pts - mean) @ axis
    lo, hi = np.percentile(t, [0.5, 99.5])
    rc = project(K, E, [[mean[0], mean[1], z]])[0]
    corner = rays_at_z(K, E, np.array([rc[0] - 0.5, rc[0] + 0.5]), np.array([rc[1] - 0.5, rc[1] + 0.5]), z)
    pixel = float(np.linalg.norm(corner[1] - corner[0])) / math.sqrt(2.0)
    lo, hi = lo - pixel / 2, hi + pixel / 2
    return dict(z=z, axis=axis, mean=mean, lo=float(lo), hi=float(hi), length=float(hi - lo), width=width, thick=float(thick))


def view_corrected(K, E, model, centre, axis, length, width, thick):
    """Return the measured length and width. Camera arguments stay for callers."""
    return float(length), float(width)


def note_dims(items, new_only=False):
    """Add the measured sizes of whole (uncut) tools to this episode's record used by dims().

    survey() records every tool it sees (both arms out of the view). relook() passes ``new_only`` and records only
    tools not measured before, so that later looks, with the right hand and the holder in the view, do not change
    the sizes taken from the clear view.
    """
    for it in items:
        if not it.get('cut') and not (new_only and DIMS.get(it['model'])):
            DIMS.setdefault(it['model'], []).append((it['length'], it['width'], it['thick']))


def _cylinder_mask(K, E, xy, shape, radius, z0, z1, n=20):
    import cv2
    ang = np.linspace(0.0, 2.0 * np.pi, n, endpoint=False)
    ring = np.c_[xy[0] + radius * np.cos(ang), xy[1] + radius * np.sin(ang)]
    pts = np.r_[np.c_[ring, np.full(n, z0)], np.c_[ring, np.full(n, z1)]]
    rc = project(K, E, pts)
    hull = cv2.convexHull(np.round(rc[:, ::-1]).astype(np.int32))
    m = np.zeros(shape, np.uint8)
    cv2.fillConvexPoly(m, hull, 1)
    return m > 0


def fit_upright_cylinder(mask, K, E, radius=0.037, z0=TABLE_Z, height=HOLDER_HEIGHT):
    """Table position of an upright cylinder of the declared size whose silhouette best overlaps ``mask``."""
    rows, cols = np.nonzero(mask)
    r0 = rows.max()
    near = ray_at_z(K, E, (r0, cols[rows >= r0 - 2].mean()), z0)[:2]
    away = near - E[:2, 3]
    best = (-1.0, near + away / np.linalg.norm(away) * radius)
    for span, step in ((0.036, 0.006), (0.006, 0.0015)):
        centre = best[1]
        for dx in np.arange(-span, span + 1e-9, step):
            for dy in np.arange(-span, span + 1e-9, step):
                xy = centre + np.array([dx, dy])
                m = _cylinder_mask(K, E, xy, mask.shape, radius, z0, z0 + height)
                iou = float((m & mask).sum()) / max(1.0, float((m | mask).sum()))
                if iou > best[0]:
                    best = (iou, xy)
    return dict(xy=best[1], iou=best[0])


def find_holder(robo, K=None, E=None):
    """The pen holder standing on the table: SAM mask in the head view and the fitted axis position."""
    if K is None:
        K, E = cam(robo)
    best = None
    for prompt in ('pencil cup', 'orange hexagonal pen holder'):
        s = segment(robo, prompt, 'cam_head', 0.3)
        if s is not None and (best is None or s['score'] > best['score']):
            best = s
        if best is not None and best['score'] >= 0.6:
            break
    if best is None:
        return None
    fit = fit_upright_cylinder(best['mask'], K, E)
    return dict(xy=fit['xy'], iou=fit['iou'], score=best['score'], prompt=best['prompt'], mask=best['mask'], seg=best['seg'])


# Direct world heights from the RGB holder reconstruction.

PINCH_FROM_UP_END = 0.032
PINCH_PEN = 0.044
RIM_Z = 0.8846
FLOOR_Z = 0.7765
# Geometry fit. docs/fill_pen_holder/geometry_fit.json
MIN_INSERTION_DEPTH = 0.043
ORDER = ['blue_marker', 'purple_marker', 'white_pen', 'black_pencil', 'yellow_black_pen']
S = dict(items=[], holder=None, hold_xy=None, placed=[], top_z=0.0)
SNAPS = []
SNAP_DETAIL = 1


def snap(robo, label, cameras=('cam_head',), detail=1):
    """Keep a labelled picture of this moment for the stage's contact sheet."""
    if detail > SNAP_DETAIL:
        return
    for c in cameras:
        im = Image.fromarray(np.asarray(robo.image(c))).convert('RGB')
        ImageDraw.Draw(im).text((6, 6), '%s %s @%d' % (label, c.replace('cam_', ''), used(robo)), fill=(255, 255, 0))
        SNAPS.append(im)


def held_width(robo, arm):
    """Width between the finger pads right now, metres (0.002 when closed on nothing, 0.111 when open). No motion."""
    return 0.002 + 0.109 * float(robo.state().arm(arm).gripper)


def clear_arms(robo, arms=('left', 'right'), gripper=None):
    return {}


def look(robo):
    """Head-view measurement of the tools on the table and the holder (arms should be clear)."""
    K, E = cam(robo)
    rgb = np.asarray(robo.image('cam_head'))
    holder = find_holder(robo, K, E)
    exclude = None
    if holder is not None:
        import cv2
        exclude = cv2.dilate(holder['mask'].astype(np.uint8), np.ones((9, 9), np.uint8)) > 0
    if S.get('hold_xy') is not None:
        hx, hy = S['hold_xy']
        held = _cylinder_mask(K, E, (hx, hy), rgb.shape[:2], 0.06, TABLE_Z, RIM_Z + 0.2007)
        right = ~table_region(K, E, rgb.shape[:2], x=(-0.47, hx - 0.095))
        exclude = held | right if exclude is None else exclude | held | right
    items = find_items(rgb, K, E, exclude=exclude)
    residue = list(RESIDUE)
    beyond = []
    if S.get('hold_xy') is not None:
        far = find_items(rgb, K, E, exclude=held, area=((hx - 0.095, hx + 0.20), (hy + 0.045, 0.24)))
        beyond = [(it['model'], np.round(it['centre'][:2], 3).tolist()) for it in far] + [('unrecognised', np.round(r['centre'], 3).tolist()) for r in RESIDUE]
    RESIDUE[:] = residue
    S['beyond'] = beyond
    for it in items:
        # Axis endpoints have no semantic polarity until the episode model reads
        # the current image using the appearance cues in EPISODE_LESSON.md.
        it.update(down=np.array(it['a']), up=np.array(it['b']),
                  orientation_confirmed=False, orientation_evidence='')
    items.sort(key=lambda it: ORDER.index(it['model']))
    return dict(items=items, holder=holder, rgb=rgb, K=K, E=E)


def survey(robo, clear=True):
    """Clear both arms, then measure the scene. Stores the result in S and returns evidence."""
    rec = clear_arms(robo) if clear else {}
    seen = look(robo)
    note_dims(seen['items'])
    S.update(items=seen['items'], holder=seen['holder'])
    pts, lines = [], []
    for it in seen['items']:
        pts.append(it['down'])
        lines.append((it['down'], it['up']))
    im = overlay(robo, 'cam_head', masks=[seen['holder']] if seen['holder'] else [], points=pts, lines=lines)
    return dict(ok=seen['holder'] is not None and len(seen['items']) > 0, clear=rec, image=im,
                holder=None if seen['holder'] is None else dict(xy=np.round(seen['holder']['xy'], 4).tolist(), iou=round(seen['holder']['iou'], 3), score=float(seen['holder']['score'])),
                items=[dict(model=it['model'], centre=np.round(it['centre'][:2], 4).tolist(), down=np.round(it['down'][:2], 4).tolist(),
                            up=np.round(it['up'][:2], 4).tolist(), length=round(it['length'], 3),
                            orientation_confirmed=it['orientation_confirmed']) for it in seen['items']])


def _segment_distance(p, a, b):
    ab = b - a
    t = np.clip(((p - a) @ ab) / max(1e-12, ab @ ab), 0.0, 1.0)
    return float(np.linalg.norm(p - (a + t * ab)))


def _can(robo, arm, xyz, pitch, yaw, roll=0.0, path='auto'):
    """Preview of one pose: True/False, or None when this cell has no previews left."""
    try:
        pv = robo.preview_move([float(v) for v in xyz], arm=arm, path=path, pitch=pitch, yaw=yaw, roll=roll)
    except Exception:
        return None
    return bool(pv.get('reachable')) and not pv.get('ik_error')


def insert_yaw_for(hold_yaw):
    """First guess of the left-hand heading from the right hand's heading (its pads lie on two opposite walls)."""
    return entry_yaw(float(hold_yaw) + 30.0)


def hold_holder(robo, yaw=None, spot=None):
    """Right hand: grasp the holder low across two walls, carry it to a spot the left hand reaches well, set it down, keep holding.

    Stops at the first step that does not work; nothing is carried unless the hand closed on the holder.
    """
    h = S['holder']
    hx, hy = float(h['xy'][0]), float(h['xy'][1])
    def clearance(c):
        return min([_segment_distance(np.array(c), it['a'][:2], it['b'][:2]) for it in S['items']] or [1.0])
    arm = robo.state().arm('right')
    pitch = float(arm.pitch)
    yaw = float(arm.yaw) if yaw is None else float(yaw)
    grasp_z = FLOOR_Z
    spot = (hx, hy) if spot is None else (float(spot[0]), float(spot[1]))
    if _can(robo, 'right', [hx, hy, grasp_z], pitch, yaw) is False:
        return dict(ok=False, holding=False, why='no reachable right-hand grasp of the holder was found', holder=[hx, hy])
    recs = [approach(robo, 'right', [hx, hy, 0.95], pitch=pitch, yaw=yaw, roll=0, path='auto', opening=1.0, label='holder-above')]
    if not recs[-1]['reached']:
        return dict(ok=False, holding=False, why='pose above the holder not reached', replies=recs)
    recs.append(go(robo, 'right', [hx, hy, grasp_z], path='line', label='holder-down'))
    if not recs[-1]['reached']:
        recs.append(go(robo, 'right', [hx, hy, 0.95], path='line', label='holder-back-up'))
        return dict(ok=False, holding=False, why='could not lower the hand around the holder', replies=recs)
    g = robo.set_gripper('right', robo.CLOSE)
    width = float(getattr(g, 'width_m', 0.0))
    holding = bool(getattr(g, 'holding', False)) and 0.055 <= width <= 0.09
    if not holding:
        robo.set_gripper('right', robo.OPEN)
        recs.append(go(robo, 'right', [hx, hy, 0.95], path='line', label='holder-back-up'))
        return dict(ok=False, holding=False, why='the hand did not close on the holder', width=width, replies=recs)
    lift = grasp_z + 0.042
    for label, xyz in (('holder-lift', [hx, hy, lift]), ('holder-carry', [spot[0], spot[1], lift]), ('holder-set', [spot[0], spot[1], grasp_z + 0.002])):
        recs.append(go(robo, 'right', xyz, path='line', gripper=robo.CLOSE, label=label))
        if not recs[-1]['reached'] and recs[-1]['dist'] > 0.012:
            tcp = np.asarray(robo.state().arm('right').tcp_pos, float)
            S.update(hold_xy=tcp[:2].copy(), hold_yaw=yaw, insert_yaw=insert_yaw_for(yaw))
            return dict(ok=False, holding=True, why=label + ' not reached; the holder is still in the hand', tcp=np.round(tcp, 4).tolist(), replies=recs)
    tcp = np.asarray(robo.state().arm('right').tcp_pos, float)
    S.update(hold_xy=tcp[:2].copy(), hold_yaw=yaw, hold_pitch=pitch, insert_yaw=insert_yaw_for(yaw), hold_z=grasp_z)
    snap(robo, 'holder held')
    return dict(ok=True, holding=True, width=width, pitch=pitch, yaw=yaw, grasp_z=grasp_z, insert_yaw=S['insert_yaw'], spot=list(spot),
                tcp=np.round(tcp, 4).tolist(), clearance=round(clearance(spot), 3), replies=recs)


LOOK_FORWARD, LOOK_UP = 0.065, 0.077


def look_down(robo, arm, xy, cam_z, yaws=(0.0, -30.0, 30.0, -60.0), label='look-down'):
    """Put an arm's wrist camera straight above a table point, looking down (closed hand). Returns the reply or None."""
    for yaw in yaws:
        h = np.array([-math.sin(math.radians(yaw)), math.cos(math.radians(yaw))])
        tcp = [xy[0] - LOOK_FORWARD * h[0], xy[1] - LOOK_FORWARD * h[1], cam_z - LOOK_UP]
        if _can(robo, arm, tcp, 60, yaw) is False:
            continue
        rec = go(robo, arm, tcp, pitch=60, yaw=yaw, roll=0, path='auto', gripper=robo.CLOSE, label=label)
        if rec['reached']:
            return rec
    return None


def entry_yaw(corner_yaw):
    """Left-hand heading for lowering tools: along a corner-to-corner line of the holder, as close to -90 degrees as the arm allows.

    The finger line is then square to a pair of walls. Headings 60 degrees apart are equivalent for a hexagon; the one
    between -100 and -40 is taken and limited to -80 (a level left hand cannot turn further at the work point), so the left hand comes in from the left and stays clear of the
    right hand behind the holder.
    """
    y = (float(corner_yaw) - 90.0) % 60.0 - 120.0
    while y < -100.0:
        y += 60.0
    while y >= -40.0:
        y -= 60.0
    return max(y, -80.0)


def measure_held_holder(robo):
    """Left wrist camera looks straight down on the held holder: its axis position and the direction of its corners."""
    hx, hy = S['hold_xy']
    rec = look_down(robo, 'left', (hx, hy), RIM_Z + 0.2007, yaws=(-30.0, -60.0, 0.0, -90.0), label='look-holder')
    if rec is None:
        return dict(ok=False, why='pose above the holder not reached')
    K, E = cam(robo, 'cam_left_wrist')
    rgb = np.asarray(robo.image('cam_left_wrist'))
    fit = fit_holder_top(rgb, K, E, guess=(hx, hy), z0=TABLE_Z + 0.002)
    snap(robo, 'holder from above', ('cam_left_wrist',))
    if fit is None or fit['iou'] < 0.85 or np.linalg.norm(fit['xy'] - np.array([hx, hy])) > 0.03:
        return dict(ok=False, why='holder outline not found from above', fit=None if fit is None else dict(iou=round(fit['iou'], 3)), reply=rec)
    S.update(hold_xy=np.array(fit['xy'], float), holder_yaw=fit['yaw'], insert_yaw=entry_yaw(fit['yaw']), hold_measured=True)
    return dict(ok=True, xy=np.round(fit['xy'], 4).tolist(), moved_from_hand_mm=round(1000 * float(np.linalg.norm(fit['xy'] - np.array([hx, hy]))), 1),
                corner_yaw=round(fit['yaw'], 1), insert_yaw=round(S['insert_yaw'], 1), iou=round(fit['iou'], 3), reply=rec)


def level_holder_grip(robo):
    """Right hand: exchange a tilted grasp of the standing holder for a level one at the hold spot.

    A holder that stood close in front of the right arm is taken with the hand tilted 30 or 45 degrees. Kept that way
    at the hold spot, the back of the hand stands above the holder: the left hand cannot lower a tool into it and the
    view from above does not show the holder's outline. The
    hold spot is within reach of a level hand, so the hand lets go, backs out upward, and takes the holder level.
    """
    pitch = float(S.get('hold_pitch', 0.0))
    if abs(pitch) < 1.0:
        return dict(ok=True, changed=False)
    hx, hy = float(S['hold_xy'][0]), float(S['hold_xy'][1])
    yaw = float(S.get('hold_yaw', 0.0))
    z = FLOOR_Z
    new_yaw = yaw
    if _can(robo, 'right', [hx, hy, z], 0.0, new_yaw) is False:
        return dict(ok=True, changed=False, why='no better grasp within reach at the hold spot; the first grasp is kept')
    robo.set_gripper('right', robo.OPEN)
    tcp = np.asarray(robo.state().arm('right').tcp_pos, float)
    recs = [go(robo, 'right', [tcp[0], tcp[1], 0.95], path='line', gripper=robo.OPEN, label='holder-release-up')]
    recs.append(go(robo, 'right', [hx, hy, 0.95], pitch=0.0, yaw=new_yaw, roll=0, path='auto', gripper=robo.OPEN, label='holder-level-above'))
    recs.append(go(robo, 'right', [hx, hy, z], path='line', gripper=robo.OPEN, label='holder-level-down'))
    g = robo.set_gripper('right', robo.CLOSE)
    width = float(getattr(g, 'width_m', 0.0))
    holding = bool(getattr(g, 'holding', False)) and 0.055 <= width <= 0.09
    if holding:
        S.update(hold_pitch=0.0, hold_yaw=new_yaw, hold_z=z, insert_yaw=insert_yaw_for(new_yaw))
    snap(robo, 'holder held level')
    return dict(ok=holding, changed=True, width=width, yaw=new_yaw, z=z, replies=recs)


def regrip_holder(robo):
    """Right hand: let go of the standing holder, take it again centred on its measured axis and as low as the hand reaches.

    After the carry the holder often sits up to 1.5 cm toward the palm, and a holder taken high (0.85 m) leaves the
    right hand's back in the way of the left fingers. Centred and low, the left hand can lower tools to its full depth.
    """
    hx, hy = float(S['hold_xy'][0]), float(S['hold_xy'][1])
    pitch, yaw, old_z = float(S.get('hold_pitch', 0.0)), float(S.get('hold_yaw', 0.0)), float(S.get('hold_z', FLOOR_Z))
    tcp = np.asarray(robo.state().arm('right').tcp_pos, float)
    z = FLOOR_Z if _can(robo, 'right', [hx, hy, FLOOR_Z], pitch, yaw) is not False else old_z
    if np.linalg.norm(tcp[:2] - np.array([hx, hy])) < 0.004 and abs(z - old_z) < 0.004:
        return dict(ok=True, changed=False)
    robo.set_gripper('right', robo.OPEN)
    rec = go(robo, 'right', [hx, hy, z], pitch=pitch, yaw=yaw, roll=0, path='line', gripper=robo.OPEN, label='holder-regrip')
    g = robo.set_gripper('right', robo.CLOSE)
    width = float(getattr(g, 'width_m', 0.0))
    holding = bool(getattr(g, 'holding', False)) and 0.055 <= width <= 0.09
    S['hold_z'] = z
    snap(robo, 'holder held again')
    return dict(ok=holding, changed=True, width=width, z=z, reply=rec)


LEFT_BASE = np.array([-0.30, -0.45])


def _hand_z(robo, arm):
    return float(np.asarray(robo.state().arm(arm).tcp_pos, float)[2])


def _lying_z(it):
    centre = None if it is None else it.get('centre')
    if centre is not None and len(centre) >= 3:
        return float(centre[2])
    return TABLE_Z


def _arm_yaw(robo, arm, stored=None):
    if stored is not None:
        return float(stored)
    return float(robo.state().arm(arm).yaw)


def move(robo, arm, xyz, label='', paths=('line', 'auto'), **kw):
    """One move, trying path styles in turn until one is reached."""
    rec = None
    for path in paths:
        rec = go(robo, arm, xyz, path=path, label=label if path == paths[0] else label + '/' + path, **kw)
        if rec['reached']:
            break
    return rec


def _pinch_pose(it, pinch):
    if not it.get('orientation_confirmed'):
        raise ValueError('Inspect the current tool image and call R.orient before choosing a pinch.')
    u = it['up'][:2] - it['down'][:2]
    u = u / np.linalg.norm(u)
    g = it['centre'][:2] + u * (dims(it['model'])['length'] / 2 - pinch)
    return g, math.degrees(math.atan2(-u[0], u[1])), u


def _reach(xy, margin=0.0):
    return True


def _segments_apart(a, b, c, d, n=7):
    return min(_segment_distance(a + (b - a) * k / (n - 1), c, d) for k in range(n))


def _wrap(deg):
    return (deg + 180.0) % 360.0 - 180.0


def fetch_item(robo, it, others=()):
    """Left hand: drag a tool whose pinch point is beyond the top-down reach closer, without turning it.

    The tool is pinched at its part nearest the robot: from straight above when that part is inside the top-down
    reach, otherwise with a tilted hand when the tool points roughly away from the robot. A far tool lying
    crosswise cannot be pinched this way (``why`` says so): rake it instead.
    """
    g, yaw_std, u = _pinch_pose(it, pinch_for(it['model']))
    length = dims(it['model'])['length']
    c = it['centre'][:2]
    t = float(np.clip((LEFT_BASE - c) @ u, -(length / 2 - 0.03), length / 2 - 0.03))
    grab = c + u * t
    d = float(np.linalg.norm(grab - LEFT_BASE))
    radial = (grab - LEFT_BASE) / d
    away = u if u @ radial >= 0 else -u
    yaw_tool = math.degrees(math.atan2(-away[0], away[1]))
    pitch, yaw = 88.0, yaw_std
    need = 0.0
    toward = (LEFT_BASE - g) / np.linalg.norm(LEFT_BASE - g)
    shift = None
    for extra in (0.0, 0.03, 0.06):
        for ang in (0, 25, -25, 50, -50, 75, -75):
            ca, sa = math.cos(math.radians(ang)), math.sin(math.radians(ang))
            dvec = np.array([ca * toward[0] - sa * toward[1], sa * toward[0] + ca * toward[1]])
            cand = dvec * (need / max(0.35, ca) + extra)
            a2, b2 = it['a'][:2] + cand, it['b'][:2] + cand
            if not _reach(g + cand, 0.03):
                continue
            if any(_segments_apart(a2, b2, o['a'][:2], o['b'][:2]) < 0.075 for o in others):
                continue
            if S.get('hold_xy') is not None and _segment_distance(np.asarray(S['hold_xy'], float), a2, b2) < 0.13:
                continue
            shift = cand
            break
        if shift is not None:
            break
    if shift is None:
        return dict(ok=False, why='no free place to drag the tool to')
    opening = 0.6 if 'marker' in it['model'] else 0.4
    up = _hand_z(robo, 'left')
    pen_z = _lying_z(it)
    recs = [approach(robo, 'left', [grab[0], grab[1], up], pitch=pitch, yaw=yaw, roll=0, path='auto', opening=opening, label='fetch-above')]
    if not recs[-1]['reached']:
        return dict(ok=False, why='pose above the tool not reached', pitch=pitch, replies=recs)
    recs.append(go(robo, 'left', [grab[0], grab[1], pen_z], path='line', label='fetch-down'))
    g_ = robo.set_gripper('left', robo.CLOSE)
    if not bool(getattr(g_, 'holding', False)):
        robo.set_gripper('left', robo.OPEN, opening=opening)
        recs.append(go(robo, 'left', [grab[0], grab[1], up], path='line', label='fetch-miss-up'))
        return dict(ok=False, why='closed on nothing', pitch=pitch, replies=recs)
    recs.append(go(robo, 'left', [grab[0], grab[1], pen_z], path='line', gripper=robo.CLOSE, label='fetch-lift'))
    recs.append(go(robo, 'left', [grab[0] + shift[0], grab[1] + shift[1], pen_z], path='line', gripper=robo.CLOSE, label='fetch-drag'))
    recs.append(go(robo, 'left', [grab[0] + shift[0], grab[1] + shift[1], pen_z], path='line', gripper=robo.CLOSE, label='fetch-set'))
    tcp = np.asarray(robo.state().arm('left').tcp_pos, float)
    moved = tcp[:2] - grab
    robo.set_gripper('left', robo.OPEN, opening=opening)
    recs.append(go(robo, 'left', [tcp[0], tcp[1], up], path='line', label='fetch-up'))
    for key in ('centre', 'a', 'b', 'up', 'down'):
        it[key] = np.array(it[key], float)
        it[key][:2] += moved
    snap(robo, 'dragged closer', detail=2)
    return dict(ok=True, pitch=pitch, grab=np.round(grab, 4).tolist(), moved=np.round(moved, 4).tolist(), replies=recs)


def rake_item(robo, it, beyond_end=False):
    """Left hand, open and tilted, reaches past a tool that lies beyond the top-down reach and pulls it toward the robot.

    The open fingers are set down beyond the tool's middle and pull it sideways; with ``beyond_end`` the closed
    hand is set down beyond the tool's far end instead and pushes it lengthwise (for a tool that points away
    from the robot). The tool's new place is not measured here: look again afterwards.
    """
    c = it['centre'][:2]
    toward = (LEFT_BASE - c) / np.linalg.norm(LEFT_BASE - c)
    yaw = max(-50.0, min(25.0, math.degrees(math.atan2(toward[0], -toward[1]))))
    h = np.array([-math.sin(math.radians(yaw)), math.cos(math.radians(yaw))])
    pull = float(dims(it['model'])['length']) / 4.0
    if beyond_end:
        far = max((it['a'][:2], it['b'][:2]), key=lambda p: float((p - c) @ h))
        start = far + h * 0.03
        end = start - h * (pull + 0.03)
        opening = None
    else:
        start = c + h * 0.05
        end = c - h * pull
        opening = 1.0
    pitch = float(robo.state().arm('left').pitch)
    pen_z = _lying_z(it)
    if not beyond_end and _can(robo, 'left', [start[0], start[1], 0.86], pitch, yaw) is False:
        half, thick = dims(it['model'])['width'] / 2, dims(it['model'])['thick']
        least = {p_: half + (thick + 0.012) / math.tan(math.radians(p_)) + 0.008 for p_ in (60.0, 50.0, 40.0)}
        for over, p in ((least[60.0], 60.0), (max(0.05, least[50.0]), 50.0), (least[50.0], 50.0), (least[40.0], 40.0)):
            cand = c + h * over
            if _can(robo, 'left', [cand[0], cand[1], 0.86], p, yaw) is not False and _can(robo, 'left', [cand[0], cand[1], pen_z], p, yaw) is not False:
                start, pitch = cand, p
                break
    recs = [approach(robo, 'left', [start[0], start[1], 0.86], pitch=pitch, yaw=yaw, roll=0, path='auto', opening=opening, label='rake-above')]
    if not recs[-1]['reached']:
        return dict(ok=False, why='pose beyond the tool not reached', pitch=pitch, replies=recs)
    recs.append(go(robo, 'left', [start[0], start[1], pen_z], path='line', label='rake-down'))
    recs.append(go(robo, 'left', [end[0], end[1], pen_z], path='line', label='rake-pull'))
    tcp = np.asarray(robo.state().arm('left').tcp_pos, float)
    recs.append(go(robo, 'left', [tcp[0], tcp[1], 0.86], path='line', label='rake-up'))
    snap(robo, 'raked')
    return dict(ok=recs[1]['reached'], pulled=round(float(np.linalg.norm(tcp[:2] - start)), 3), yaw=yaw, beyond_end=beyond_end, replies=recs)


def uncrowd_item(robo, it, others=()):
    """Left hand: drag a tool that lies against the held holder (or under the right hand) clear of it, without turning it.

    The tool is pinched from above at its part farthest from the hold spot, lifted a few millimetres and dragged
    straight away from the holder until all of it is 17 cm or more from the hold spot. Its record is moved along.
    """
    hold = np.asarray(S['hold_xy'], float)
    length = dims(it['model'])['length']
    _, yaw, u = _pinch_pose(it, pinch_for(it['model']))
    c = it['centre'][:2]
    ends = [c + u * k for k in (-(length / 2 - 0.03), length / 2 - 0.03)]
    grab = max(ends, key=lambda p: float(np.linalg.norm(p - hold)))
    if np.linalg.norm(grab - hold) < 0.15 or not _reach(grab):
        return dict(ok=False, why='no part of the tool is clear of the holder and within reach')
    nearest = _segment_distance(hold, it['a'][:2], it['b'][:2])
    need = float(np.clip(0.17 - nearest, 0.04, 0.13))
    away = (c - hold) / np.linalg.norm(c - hold)
    shift = None
    for ang in (0, 25, -25, 50, -50, 75, -75):
        ca, sa = math.cos(math.radians(ang)), math.sin(math.radians(ang))
        dvec = np.array([ca * away[0] - sa * away[1], sa * away[0] + ca * away[1]])
        cand = dvec * need / max(0.4, ca)
        a2, b2 = it['a'][:2] + cand, it['b'][:2] + cand
        if not _reach(grab + cand, 0.02) or not _reach(_pinch_pose(it, pinch_for(it['model']))[0] + cand, 0.02):
            continue
        if any(_segments_apart(a2, b2, o['a'][:2], o['b'][:2]) < 0.06 for o in others):
            continue
        shift = cand
        break
    if shift is None:
        return dict(ok=False, why='no free place to drag the tool to')
    opening = 0.6 if 'marker' in it['model'] else 0.4
    up = _hand_z(robo, 'left')
    pen_z = _lying_z(it)
    recs = [approach(robo, 'left', [grab[0], grab[1], up], pitch=88, yaw=yaw, roll=0, path='auto', opening=opening, label='uncrowd-above')]
    if not recs[-1]['reached']:
        return dict(ok=False, why='pose above the tool not reached', replies=recs)
    recs.append(go(robo, 'left', [grab[0], grab[1], pen_z], path='line', label='uncrowd-down'))
    if float(robo.state().arm('left').tcp_pos[2]) > pen_z + 0.012:
        recs.append(go(robo, 'left', [grab[0], grab[1], up], path='line', label='uncrowd-blocked-up'))
        return dict(ok=False, why='descent blocked at the far part of the tool too', replies=recs)
    g_ = robo.set_gripper('left', robo.CLOSE)
    if not bool(getattr(g_, 'holding', False)):
        robo.set_gripper('left', robo.OPEN, opening=opening)
        recs.append(go(robo, 'left', [grab[0], grab[1], up], path='line', label='uncrowd-miss-up'))
        return dict(ok=False, why='closed on nothing', replies=recs)
    recs.append(go(robo, 'left', [grab[0], grab[1], pen_z], path='line', gripper=robo.CLOSE, label='uncrowd-lift'))
    recs.append(go(robo, 'left', [grab[0] + shift[0], grab[1] + shift[1], pen_z], path='line', gripper=robo.CLOSE, label='uncrowd-drag'))
    recs.append(go(robo, 'left', [grab[0] + shift[0], grab[1] + shift[1], pen_z], path='line', gripper=robo.CLOSE, label='uncrowd-set'))
    tcp = np.asarray(robo.state().arm('left').tcp_pos, float)
    moved = tcp[:2] - grab
    robo.set_gripper('left', robo.OPEN, opening=opening)
    recs.append(go(robo, 'left', [tcp[0], tcp[1], up], path='line', label='uncrowd-up'))
    for key in ('centre', 'a', 'b', 'up', 'down'):
        it[key] = np.array(it[key], float)
        it[key][:2] += moved
    snap(robo, 'dragged clear of the holder', detail=2)
    return dict(ok=float(np.linalg.norm(moved)) > 0.02, why=None if np.linalg.norm(moved) > 0.02 else 'the tool did not move', moved=np.round(moved, 4).tolist(), grab=np.round(grab, 4).tolist(), replies=recs)


def pick_item(robo, it, pinch=None, others=(), retry=True):
    """Left hand: pinch a lying tool from above near the end that must stay up, heading toward that end, and lift it a little."""
    if not it.get('orientation_confirmed'):
        return dict(ok=False, holding=False, why='Tool orientation needs current RGB review with R.orient.')
    try:
        model = dims(it['model'])
    except ValueError as exc:
        return dict(ok=False, holding=False, why=str(exc))
    pinch = pinch_for(it['model']) if pinch is None else pinch
    g_xy, yaw, u = _pinch_pose(it, pinch)
    fetched = None
    if not _reach(g_xy):
        fetched = fetch_item(robo, it, others)
        if not fetched['ok'] and 'no part' in str(fetched.get('why')):
            snap(robo, 'before rake')
            raked = rake_item(robo, it, beyond_end=bool(it.get('rake_failed')))
            return dict(ok=False, holding=False, why='tool was beyond reach; pulled it closer, look again', rake=raked)
        if not fetched['ok']:
            return dict(ok=False, holding=False, why='tool is out of reach and could not be dragged closer', fetch=fetched)
        g_xy, yaw, u = _pinch_pose(it, pinch)
    opening = 0.6 if 'marker' in it['model'] else 0.4
    out = dict(yaw=yaw, pinch_xy=np.round(g_xy, 4).tolist(), fetch=fetched)
    up = _hand_z(robo, 'left')
    pen_z = _lying_z(it)
    recs = [approach(robo, 'left', [g_xy[0], g_xy[1], up], pitch=88, yaw=yaw, roll=0, path='auto', opening=opening, label='pick-above')]
    if not recs[-1]['reached']:
        return dict(out, ok=False, holding=False, why='pose above the tool not reached', replies=recs)
    recs.append(go(robo, 'left', [g_xy[0], g_xy[1], pen_z], path='line', label='pick-down'))
    if float(robo.state().arm('left').tcp_pos[2]) > pen_z + 0.012:
        recs.append(go(robo, 'left', [g_xy[0], g_xy[1], up], path='line', label='pick-blocked-up'))
        if not retry:
            return dict(out, ok=False, holding=False, why='the hand could not come down on the tool (something is in its way)', replies=recs)
        freed = uncrowd_item(robo, it, others)
        if not freed['ok']:
            return dict(out, ok=False, holding=False, why='the hand could not come down on the tool and the tool could not be dragged clear: %s' % freed.get('why'), uncrowd=freed, replies=recs)
        again = pick_item(robo, it, pinch=pinch, others=others, retry=False)
        again['uncrowd'] = brief(freed)
        return again
    g = robo.set_gripper('left', robo.CLOSE)
    width = float(getattr(g, 'width_m', 0.0))
    holding = bool(getattr(g, 'holding', False)) and width > 0.5 * min(model['width'], model['thick'])
    snap(robo, 'pinched ' + it['model'], ('cam_left_wrist',))
    snap(robo, 'pinched', ('cam_head',), detail=2)
    if not holding:
        robo.set_gripper('left', robo.OPEN, opening=opening)
        recs.append(go(robo, 'left', [g_xy[0], g_xy[1], up], path='line', label='pick-miss-up'))
        return dict(out, ok=False, holding=False, why='closed on nothing', width=width, replies=recs)
    recs.append(go(robo, 'left', [g_xy[0], g_xy[1], up], path='line', gripper=robo.CLOSE, label='pick-lift'))
    robo.set_gripper('left', robo.CLOSE)
    if held_width(robo, 'left') < 0.5 * min(model['width'], model['thick']):
        robo.set_gripper('left', robo.OPEN, opening=opening)
        return dict(out, ok=False, holding=False, why='tool slipped out while lifting', width=width, replies=recs)
    return dict(out, ok=True, holding=True, width=width, replies=recs)


def measure_hang(robo, it, hang):
    """How far forward the hanging tool leans in the left hand, from the head camera (no motion).

    A tool sags a little in the pinch while it is carried level; turned upright it keeps that angle, so its lower
    end hangs ahead of the fingers (along the hand's heading), never sideways (the pads hold it). The head image is
    scanned along straight lines from the fingers downward at lean angles from -12 to +32 degrees; the line with
    the most tool-coloured pixels on it and bare table beyond its end is the tool. Returns the lean in degrees and
    the forward offset of the lower end, or no lean when the tool is not seen clearly.
    """
    K, E = cam(robo)
    rgb = np.asarray(robo.image('cam_head'))
    cls = colour_classes(rgb)
    fg = cls['white'] | cls['blue'] | cls['purple'] | cls['dark'] | cls['yellow']
    arm = robo.state().arm('left')
    tcp = np.asarray(arm.tcp_pos, float)
    yaw = math.radians(float(arm.yaw))
    h = np.array([-math.sin(yaw), math.cos(yaw), 0.0])
    rows = []
    for a in np.arange(-12.0, 32.1, 1.0):
        d = np.array([0.0, 0.0, -math.cos(math.radians(a))]) + h * math.sin(math.radians(a))
        on = project(K, E, [tcp + d * s_ for s_ in np.linspace(0.035, hang - 0.004, 22)])
        off = project(K, E, [tcp + d * s_ for s_ in np.linspace(hang + 0.012, hang + 0.03, 5)])
        def share(rc):
            hits = [fg[int(round(r)), int(round(c))] for r, c in rc if 0 <= int(round(r)) < fg.shape[0] and 0 <= int(round(c)) < fg.shape[1]]
            return float(np.mean(hits)) if hits else 0.0
        rows.append((share(on) - 0.5 * share(off), a, share(on), share(off)))
    top = max(r[0] for r in rows)
    good = [r for r in rows if r[0] >= top - 0.06]
    best = good[len(good) // 2]
    seen = best is not None and best[2] >= 0.7 and best[3] <= 0.4
    lean = float(best[1]) if seen else 0.0
    return dict(seen=bool(seen), lean=lean, forward=hang * math.sin(math.radians(lean)), on_line=round(best[2], 2), beyond=round(best[3], 2))


def insert_item(robo, it, offset=(0.0, 0.0), roll=0.0, pinch=None, side=None):
    """Left hand: carry the pinched tool to the work point, turn it upright (insertion end down), lower it into the held holder, let go.

    The tool travels above everything that already stands in the holder. The hand only opens after it has lowered
    the tool into the holder. On any earlier stop the tool is still held.
    """
    if not it.get('orientation_confirmed'):
        return dict(ok=False, holding=True, why='Tool orientation needs current RGB review with R.orient.')
    try:
        model = dims(it['model'])
    except ValueError as exc:
        return dict(ok=False, holding=True, why=str(exc))
    pinch = pinch_for(it['model']) if pinch is None else pinch
    hang = model['length'] - pinch
    hx, hy = S['hold_xy']
    iyaw = _arm_yaw(robo, 'left', S.get('insert_yaw'))
    here = np.asarray(robo.state().arm('left').tcp_pos, float)
    turn_z = max(0.98, TABLE_Z + hang + 0.045)
    recs = [move(robo, 'left', [here[0], here[1], turn_z], pitch=88, yaw=iyaw, roll=0, gripper=robo.CLOSE, label='carry-level')]
    if not recs[-1]['reached']:
        return dict(ok=False, holding=True, why='carry to the work point not reached', replies=recs)
    for step_pitch in (58.0, 29.0, 0.0):
        recs.append(move(robo, 'left', [here[0], here[1], turn_z], pitch=step_pitch, yaw=iyaw, roll=0, gripper=robo.CLOSE,
                         label='upright-%d' % step_pitch, paths=('line', 'auto')))
    if not recs[-1]['reached'] and not recs[-1]['dist'] < 0.015:
        return dict(ok=False, holding=True, why='turning upright not reached', replies=recs)
    snap(robo, 'upright', detail=2)
    if held_width(robo, 'left') < 0.5 * min(model['width'], model['thick']):
        return dict(ok=False, holding=False, why='tool was lost while turning', replies=recs)
    hover_z = max(RIM_Z + 0.0307, S['top_z'] + 0.02) + hang
    target = [hx + offset[0], hy + offset[1]]
    lean = None
    recs.append(move(robo, 'left', [here[0], here[1], hover_z], gripper=robo.CLOSE, label='rise-to-carry'))
    if side is not None:
        start = [hx + side[0], hy + side[1]]
        recs.append(move(robo, 'left', start + [hover_z], pitch=0, yaw=iyaw, roll=roll, gripper=robo.CLOSE, label='hover-beside'))
        if not recs[-1]['reached']:
            return dict(ok=False, holding=True, why='pose beside the holder not reached', replies=recs)
        try:
            lean = measure_hang(robo, it, hang)
        except Exception as exc:
            lean = dict(seen=False, lean=0.0, forward=0.0, error=str(exc)[:120])
        snap(robo, 'hanging beside holder ' + it['model'], detail=2)
        used_lean = float(lean['lean']) if lean.get('seen') else 0.0
        lean = dict(lean, used=used_lean, forward_used=hang * math.sin(math.radians(used_lean)))
        back = np.array([-math.sin(math.radians(iyaw)), math.cos(math.radians(iyaw))]) * lean['forward_used']
        start = [start[0] - back[0], start[1] - back[1]]
        target = [target[0] - back[0], target[1] - back[1]]
        recs.append(go(robo, 'left', start + [RIM_Z + 0.0157 + hang], path='line', gripper=robo.CLOSE, label='lower-beside'))
        snap(robo, 'beside holder ' + it['model'], detail=2)
        recs.append(go(robo, 'left', target + [RIM_Z + 0.0157 + hang], path='line', gripper=robo.CLOSE, label='slide-in'))
        if not recs[-1]['reached'] and recs[-1]['dist'] > 0.01:
            return dict(ok=False, holding=True, why='could not move the tool over the rim', replies=recs)
    else:
        recs.append(move(robo, 'left', target + [hover_z], pitch=0, yaw=iyaw, roll=roll, gripper=robo.CLOSE, label='hover'))
        if not recs[-1]['reached']:
            return dict(ok=False, holding=True, why='pose over the holder not reached', replies=recs)
    snap(robo, 'over holder ' + it['model'])
    release_z = max(FLOOR_Z + hang + 0.012, LEFT_LEVEL_MIN_Z, S.get('marker_top', 0.0) + (0.015 if 'marker' in it['model'] else 0.008))
    recs.append(go(robo, 'left', target + [release_z], path='line', gripper=robo.CLOSE, label='lower'))
    tcp = np.asarray(robo.state().arm('left').tcp_pos, float)
    if tcp[2] > release_z + 0.02 and tcp[2] - hang > RIM_Z - MIN_INSERTION_DEPTH:
        return dict(ok=False, holding=True, why='could not lower the tool into the holder', tcp=np.round(tcp, 4).tolist(), replies=recs)
    snap(robo, 'lowered', detail=2)
    if 'marker' in it['model']:
        robo.set_gripper('left', robo.OPEN)
    else:
        robo.set_gripper('left', robo.OPEN, opening=0.45)
    recs.append(go(robo, 'left', [tcp[0], tcp[1], hover_z], path='line', gripper=robo.OPEN, label='rise'))
    snap(robo, 'released ' + it['model'])
    S['placed'].append(it['model'])
    S['top_z'] = max(S['top_z'], FLOOR_Z + model['length'])
    if 'marker' in it['model']:
        S['marker_top'] = max(S.get('marker_top', 0.0), FLOOR_Z + model['length'])
    return dict(ok=True, holding=False, hover_z=hover_z, release_z=release_z, roll=roll, lean=lean, tcp=np.round(tcp, 4).tolist(), replies=recs)




def finish(robo, route=None):
    """Release the holder and return both arms home; do not waste actions.

    The default full route raises the right hand above the tools before leaving.
    Explicit 'short' and 'fast' routes require the caller to assess clearance.
    """
    recs = []
    if route is None:
        route = 'full'
    left = np.asarray(robo.state().arm('left').tcp_pos, float)
    if S.get('hold_xy') is not None and np.linalg.norm(left[:2] - np.asarray(S['hold_xy'], float)) < 0.16:
        if route == 'full':
            recs.append(move(robo, 'left', [left[0], left[1], max(left[2], 1.0)], label='left-away'))
        elif left[2] < 1.0:
            recs.append(go(robo, 'left', [left[0], left[1], 1.03], path='line', gripper=robo.OPEN, label='left-up'))
    robo.set_gripper('right', robo.OPEN)
    tcp = np.asarray(robo.state().arm('right').tcp_pos, float)
    yaw = math.radians(float(S.get('hold_yaw') or 0.0))
    back = np.array([math.sin(yaw), -math.cos(yaw)])
    recs.append(go(robo, 'right', [tcp[0] + 0.13 * back[0], tcp[1] + 0.13 * back[1], tcp[2]], path='line', gripper=robo.OPEN, label='holder-withdraw'))
    out = np.asarray(robo.state().arm('right').tcp_pos, float)
    if route in ('full', 'short'):
        recs.append(move(robo, 'right', [out[0], out[1], 1.05], gripper=robo.OPEN, label='right-up'))
    if route == 'full':
        recs.append(move(robo, 'right', [0.30, -0.207, 1.03], gripper=robo.OPEN, label='right-clear-high'))
    snap(robo, 'holder released')
    home = None
    for _ in range(3):
        home = robo.home()
        if bool(getattr(home, 'reached', False)):
            break
    snap(robo, 'home')
    return dict(ok=bool(getattr(home, 'reached', False)), route=route, replies=recs, home=str(home)[:300])


LEFT_LEVEL_MIN_Z = 1.036


def pinch_for(model):
    """Distance of the pinch from the end that stays up."""
    return PINCH_FROM_UP_END if 'marker' in model else PINCH_PEN


def slot_for(model, placed):
    """Entry point of the next tool (offset from the holder's axis, world), hand roll, and for a thin pen the side entry.

    A thin pen that comes straight down beside the standing markers has about 2 mm to spare on either side, and lands
    on a marker top or on the rim when it is a little off. So once markers stand in the holder a pen is brought in from
    the open side instead: its lower end is lowered to just above the rim outside the holder, moved sideways over the
    rim until it lies against the markers' faces (they lean on the opposite wall, so their faces are where the wall
    puts them), and only then lowered along those faces. ``side`` is the starting offset of that sideways move.
    """
    kind = 'marker' if 'marker' in model else 'pen'
    yaw = math.radians(float(S.get('insert_yaw', 0.0)))
    fingers = np.array([-math.cos(yaw), -math.sin(yaw)])
    widths = [dims(p)['width'] for p in placed if 'marker' in p]
    if kind == 'pen' and widths:
        face = -HOLDER_INNER_FLAT + max(widths)
        across = face + dims(model)['width'] / 2
        return tuple(across * fingers), 0.0, tuple(0.050 * fingers)
    return (0.0, 0.0), 0.0, None


def place_item(robo, it, others=()):
    """Pick one tool and put it into the held holder. Returns evidence; ``ok`` means it was released inside the holder."""
    pick = pick_item(robo, it, others=others)
    if not pick['ok']:
        return dict(ok=False, stage='pick', pick=pick)
    offset, roll, side = slot_for(it['model'], S['placed'])
    ins = insert_item(robo, it, offset=offset, roll=roll, side=side)
    return dict(ok=ins['ok'], stage='insert', pick=pick, insert=ins)


def put_down(robo, it=None):
    """Left hand: lay a held tool back on the table near the work point (used when it cannot be lowered into the holder).

    The tool is laid down level, pointing along the hand's heading, at a place clear of the other tools; its record is updated.
    """
    tcp = np.asarray(robo.state().arm('left').tcp_pos, float)
    yaw = _arm_yaw(robo, 'left', S.get('insert_yaw'))
    h = np.array([-math.sin(math.radians(yaw)), math.cos(math.radians(yaw))])
    recs = [move(robo, 'left', [tcp[0], tcp[1], max(tcp[2], 0.98)], gripper=robo.CLOSE, label='putdown-to-work')]
    recs.append(move(robo, 'left', [tcp[0], tcp[1], 0.98], pitch=88, yaw=yaw, roll=0, gripper=robo.CLOSE, label='putdown-level', paths=('auto', 'line')))
    length = dims(it['model'])['length'] if it is not None else 0.16
    pinch = pinch_for(it['model']) if it is not None else 0.04
    others = [o for o in S['items'] if o is not it and not o.get('done')]
    spot = None
    for dx, dy in ((0.0, 0.0), (-0.07, -0.05), (-0.14, -0.02), (0.0, -0.09), (-0.07, 0.06), (-0.16, 0.08), (0.04, 0.05)):
        cand = np.array([tcp[0] + dx, tcp[1] + dy])
        a2, b2 = cand + h * pinch, cand - h * (length - pinch)
        if _reach(cand, 0.02) and all(_segments_apart(a2, b2, o['a'][:2], o['b'][:2]) > 0.05 for o in others):
            spot = cand
            break
    spot = tcp[:2] if spot is None else spot
    recs.append(go(robo, 'left', [spot[0], spot[1], _lying_z(it)], path='line', gripper=robo.CLOSE, label='putdown-lower'))
    robo.set_gripper('left', robo.OPEN)
    tcp = np.asarray(robo.state().arm('left').tcp_pos, float)
    recs.append(go(robo, 'left', [tcp[0], tcp[1], 0.90], path='line', gripper=robo.OPEN, label='putdown-up'))
    if it is not None:
        up, down = tcp[:2] + h * pinch, tcp[:2] - h * (length - pinch)
        z = it['centre'][2]
        it.update(up=np.array([up[0], up[1], z]), down=np.array([down[0], down[1], z]), a=np.array([up[0], up[1], z]), b=np.array([down[0], down[1], z]),
                  centre=np.array([(up[0] + down[0]) / 2, (up[1] + down[1]) / 2, z]), axis=np.array([h[0], h[1], 0.0]))
    return dict(ok=recs[-1]['reached'], at=np.round(tcp[:2], 3).tolist(), replies=recs)


def nudge(robo, xy):
    """Left hand, closed, sweeps 9 cm toward the robot through a heap of touching tools to spread them. Look again afterwards."""
    xy = np.asarray(xy, float)[:2]
    toward = (LEFT_BASE - xy) / np.linalg.norm(LEFT_BASE - xy)
    yaw = max(-50.0, min(25.0, math.degrees(math.atan2(toward[0], -toward[1]))))
    start, end = xy - toward * 0.035, xy + toward * 0.055
    pitch = 88.0 if _reach(start, 0.01) else float(robo.state().arm('left').pitch)
    recs = [approach(robo, 'left', [start[0], start[1], 0.86], pitch=pitch, yaw=yaw, roll=0, path='auto', label='nudge-above')]
    if not recs[-1]['reached']:
        return dict(ok=False, why='pose over the heap not reached', replies=recs)
    recs.append(go(robo, 'left', [start[0], start[1], TABLE_Z], path='line', label='nudge-down'))
    recs.append(go(robo, 'left', [end[0], end[1], TABLE_Z], path='line', label='nudge-sweep'))
    tcp = np.asarray(robo.state().arm('left').tcp_pos, float)
    recs.append(go(robo, 'left', [tcp[0], tcp[1], 0.86], path='line', label='nudge-up'))
    return dict(ok=True, replies=recs)


def relook(robo):
    """Left arm out of the view, then measure which tools still lie on the table (the holder stays in the right hand)."""
    rec = clear_arms(robo, arms=('left',), gripper=robo.OPEN)
    old = [it for it in S['items'] if not it.get('done')]
    seen = look(robo)
    note_dims(seen['items'], new_only=True)
    for it in seen['items']:
        same = [o for o in old if o['model'] == it['model'] and not o.get('matched')]
        if same:
            near = min(same, key=lambda o: float(np.linalg.norm(o['centre'][:2] - it['centre'][:2])))
            near['matched'] = True
            it['miss'] = near.get('miss', 0)
            it['miss_lying'] = near.get('miss_lying', 0)
            turned = abs(float(near['axis'][:2] @ it['axis'][:2]))
            still = np.linalg.norm(near['centre'][:2] - it['centre'][:2]) < 0.03 and turned > 0.94
            unique = (sum(o['model'] == it['model'] for o in old) == 1
                      and sum(o['model'] == it['model'] for o in seen['items']) == 1)
            if still and near.get('orientation_confirmed') and unique:
                toward_down = near['down'][:2] - near['centre'][:2]
                ends = sorted((it['a'], it['b']), key=lambda p: -float((p[:2] - it['centre'][:2]) @ toward_down))
                it.update(down=np.array(ends[0]), up=np.array(ends[1]),
                          orientation_confirmed=True, orientation_evidence=near['orientation_evidence'])
            if near.get('raked_at') is not None and np.linalg.norm(np.asarray(near['raked_at']) - it['centre'][:2]) < 0.02:
                it['rake_failed'] = True
    S['items'] = seen['items']
    S['residue'] = [np.round(r['centre'], 3).tolist() for r in RESIDUE]
    snap(robo, 'table now')
    return dict(ok=True, clear=rec, left=[(it['model'], np.round(it['centre'][:2], 3).tolist()) for it in seen['items']], unrecognised=S['residue'],
                beyond_holder=S.get('beyond', []))




def fill(robo, log=None, rounds=10):
    """Hold the holder (if it is not held yet) and place every tool that lies on the table, looking again after a miss.

    Returns for RGB endpoint review, when no tool remains, or after repeated failures.
    """
    log = log or (lambda *a: None)
    out = dict(ok=False, placed=[], events=[])
    def orientation_review():
        pending = [i for i, it in enumerate(S['items'])
                   if not it.get('done') and not it.get('orientation_confirmed')]
        if pending:
            return dict(out, why='Inspect the labelled tool endpoints and call R.orient for each pending tool, then R.fill again.',
                        needs_orientation=pending)
    review = orientation_review()
    if review is not None:
        return review
    missing = [i for i, it in enumerate(S['items'])
               if not it.get('done') and not DIMS.get(it['model'])
               and it['model'] not in RGB_TOOL_DIMS]
    if missing:
        return dict(out, why='Whole-tool RGB size measurements needed; survey or relook with the tools fully visible.',
                    needs_dimensions=missing)
    if S.get('hold_xy') is None:
        r = hold_holder(robo)
        log('HOLD', brief(r))
        out['hold'] = brief(r)
        if not r['ok']:
            return dict(out, why='holder: ' + str(r.get('why')))
    if not S.get('hold_measured') and abs(float(S.get('hold_pitch', 0.0))) >= 1.0:
        r = level_holder_grip(robo)
        log('HOLDER HELD LEVEL', brief(r))
        out['holder_held_level'] = brief(r)
        if not r['ok']:
            return dict(out, why='the right hand did not close on the holder again (level grasp)')
    if not S.get('hold_measured'):
        r = measure_held_holder(robo)
        log('HOLDER FROM ABOVE', brief(r))
        out['holder_from_above'] = brief(r)
        if r['ok']:
            g = regrip_holder(robo)
            log('HOLDER TAKEN AGAIN', brief(g))
            out['holder_taken_again'] = brief(g)
            if not g['ok']:
                return dict(out, why='the right hand did not close on the holder again')
    for round_ in range(rounds):
        review = orientation_review()
        if review is not None:
            return review
        lying = sum(1 for it in S['items'] if not it.get('done'))
        for it in S['items']:
            if not it.get('done') and it.get('miss', 0) >= 3 and lying < it.get('miss_lying', 0):
                it['miss'] = 1
        todo = [it for it in S['items'] if not it.get('done') and it.get('miss', 0) < 3]
        markers_in = sum(1 for p in S['placed'] if 'marker' in p)
        if markers_in < 2 and not any('marker' in it['model'] for it in todo) and S.get('residue') and out.get('nudges', 0) < 2:
            out['nudges'] = out.get('nudges', 0) + 1
            log('NUDGE', S['residue'][0], brief(nudge(robo, S['residue'][0])))
            seen = relook(robo)
            log('TABLE', seen['left'], seen['unrecognised'])
            continue
        if not todo:
            break
        todo.sort(key=lambda it: (0 if 'marker' in it['model'] else 1, it.get('miss', 0), ORDER.index(it['model'])))
        missed = False
        for it in todo:
            others = [o for o in S['items'] if o is not it and not o.get('done')]
            r = place_item(robo, it, others=others)
            it['done'] = bool(r['ok'])
            log('PLACE', it['model'], brief(r), 'used', used(robo))
            out['events'].append(dict(model=it['model'], ok=bool(r['ok']), stage=r['stage'], why=(r.get(r['stage']) or {}).get('why'), at=used(robo)))
            if r['ok']:
                out['placed'].append(it['model'])
                continue
            missed = True
            it['miss'] = it.get('miss', 0) + 1
            it['miss_lying'] = sum(1 for o in S['items'] if not o.get('done'))
            if (r.get('pick') or {}).get('rake') is not None:
                it['raked_at'] = np.array(it['centre'][:2], float)
            if (r.get('insert') or {}).get('holding'):
                it['held'] = True
                pd = put_down(robo, it)
                it['held'] = False
                log('PUT DOWN', brief(pd))
            break
        seen = relook(robo)
        log('TABLE', seen['left'])
        out['left_on_table'] = seen['left']
        out['unrecognised_on_table'] = seen['unrecognised']
        out['beyond_holder'] = seen['beyond_holder']
        if not seen['left']:
            if not seen['unrecognised'] and seen['beyond_holder']:
                return dict(out, why='a tool lies on the table behind the holder, out of reach of these routines: %s' % seen['beyond_holder'])
            if not seen['unrecognised']:
                return dict(out, ok=True)
            if out.get('nudges', 0) >= 2:
                return dict(out, why='something that is not recognised as a single tool lies on the table (tools touching or crossing?)')
            out['nudges'] = out.get('nudges', 0) + 1
            log('NUDGE', seen['unrecognised'][0], brief(nudge(robo, seen['unrecognised'][0])))
            seen = relook(robo)
            log('TABLE', seen['left'], seen['unrecognised'])
            out['left_on_table'], out['unrecognised_on_table'] = seen['left'], seen['unrecognised']
        if not missed:
            for it in S['items']:
                it['miss'] = it.get('miss', 0) + 1
    review = orientation_review()
    if review is not None:
        return review
    left = [it['model'] for it in S['items'] if not it.get('done')]
    return dict(out, ok=not left, why=None if not left else 'tools are still on the table', left=left)


NAMES = {'purple_marker': 'purple marker', 'blue_marker': 'light-blue marker', 'black_pencil': 'black pencil',
         'white_pen': 'white pen', 'yellow_black_pen': 'black pen with yellow ends'}


class Routines:
    """Stage calls for one episode. Each returns a dict: ok, reason, measured, image (a labelled picture or contact sheet)."""

    def __init__(self, robo):
        self.robo = robo
        right = robo.state().arm('right')
        if S.get('hold_xy') is None and 0.055 <= 0.002 + 0.109 * float(right.gripper) <= 0.09 and right.tcp_pos[2] < 0.88:
            S.update(hold_xy=np.asarray(right.tcp_pos, float)[:2], hold_yaw=float(right.yaw), insert_yaw=insert_yaw_for(float(right.yaw)))

    def _out(self, ok, reason, measured, image=None):
        if image is None and SNAPS:
            image = sheet(SNAPS, cols=4)
        del SNAPS[:]
        return dict(ok=bool(ok), reason=reason, measured=measured, action_count=self.robo.action_count(), image=image)

    def show(self, out, display):
        """Print the result without the picture, then show the picture."""
        print(json.dumps({k: v for k, v in out.items() if k != 'image'}, default=str))
        if out.get('image') is not None:
            display(out['image'])

    def _tools(self):
        rows = []
        for i, it in enumerate(S['items']):
            rows.append(dict(index=i, tool=NAMES[it['model']], centre=np.round(it['centre'][:2], 3).tolist(),
                             endpoints={end: np.round(it[end], 4).tolist() for end in ('a', 'b')},
                             down_end=np.round(it['down'][:2], 3).tolist() if it.get('orientation_confirmed') else None,
                             end_decision='selected from RGB' if it.get('orientation_confirmed') else 'NEEDS RGB REVIEW',
                             orientation_evidence=it.get('orientation_evidence', ''), placed=bool(it.get('done'))))
        return rows

    def _picture(self):
        K, E = cam(self.robo)
        im = Image.fromarray(np.asarray(self.robo.image('cam_head'))).convert('RGB').resize((1280, 960), Image.LANCZOS)
        dr = ImageDraw.Draw(im)
        for i, it in enumerate(S['items']):
            (r0, c0), (r1, c1) = project(K, E, [it['down'], it['up']]) * 2
            dr.line([(c0, r0), (c1, r1)], fill=(0, 255, 0), width=1)
            if it.get('orientation_confirmed'):
                dr.ellipse([c0 - 6, r0 - 6, c0 + 6, r0 + 6], outline=(255, 0, 0), width=3)
            dr.text((c1 + 8, r1 - 6), '%d %s' % (i, NAMES[it['model']]), fill=(255, 255, 0))
            for end, (r, c) in zip(('a', 'b'), project(K, E, [it['a'], it['b']]) * 2):
                dr.text((c + 6, r + 8), '%d:%s' % (i, end), fill=(255, 255, 255))
        if S.get('holder') is not None and S.get('hold_xy') is None:
            r, c = project(K, E, [S['holder']['xy'][0], S['holder']['xy'][1], RIM_Z])[0] * 2
            dr.ellipse([c - 8, r - 8, c + 8, r + 8], outline=(255, 0, 255), width=3)
        if not S['items']:
            return im
        raw = Image.fromarray(np.asarray(self.robo.image('cam_head'))).convert('RGB')
        out = Image.new('RGB', (1280, 960 + 320))
        out.paste(im, (0, 0))
        for i, it in enumerate(S['items'][:4]):
            (r0, c0), (rc_, cc_) = project(K, E, [it['down'], it['centre']])
            box = [int(cc_) - 40, int(rc_) - 40, int(cc_) + 40, int(rc_) + 40]
            crop = raw.crop(box).resize((320, 320), Image.LANCZOS)
            d2 = ImageDraw.Draw(crop)
            x, y = (c0 - box[0]) * 4, (r0 - box[1]) * 4
            if it.get('orientation_confirmed'):
                d2.ellipse([x - 14, y - 14, x + 14, y + 14], outline=(255, 0, 0), width=3)
            for end, (r, c) in zip(('a', 'b'), project(K, E, [it['a'], it['b']])):
                d2.text(((c - box[0]) * 4 + 6, (r - box[1]) * 4 + 8), end, fill=(255, 255, 255))
            d2.text((6, 6), '%d %s' % (i, NAMES[it['model']]), fill=(255, 255, 0))
            out.paste(crop, (i * 320, 960))
        return out

    def survey(self):
        """Find the holder and tools; label endpoints for the episode model's RGB review."""
        r = survey(self.robo)
        del SNAPS[:]
        n = len(S['items'])
        reason = None if r['ok'] and n == 4 else ('holder not found' if S['holder'] is None else '%d tools found, 4 expected' % n)
        return self._out(r['ok'] and n == 4, reason, dict(holder=r['holder'], tools=self._tools()), self._picture())

    def orient(self, index, down_end, evidence):
        """Record the episode model's current RGB choice of endpoint 'a' or 'b'; no motion.

        Describe the visible tip/cap/tail cue in evidence. This records a visual
        decision; it does not independently verify that the decision is correct.
        """
        if down_end not in ('a', 'b') or not isinstance(evidence, str) or not evidence.strip():
            raise ValueError('Choose endpoint a or b and describe its visible RGB cue.')
        if not isinstance(index, int) or not 0 <= index < len(S['items']):
            raise ValueError('Use a tool index from the latest survey/status output.')
        it = S['items'][index]
        if it.get('done'):
            raise ValueError('Cannot change the orientation of an already placed tool.')
        it.update(down=np.array(it[down_end]), up=np.array(it['b' if down_end == 'a' else 'a']),
                  orientation_confirmed=True, orientation_evidence=evidence.strip())
        return self._out(True, None, dict(tools=self._tools()), self._picture())

    def flip(self, index, evidence):
        """Reverse a selected endpoint after current RGB review; no motion."""
        it = S['items'][int(index)]
        if not it.get('orientation_confirmed'):
            raise ValueError('Use R.orient to select an endpoint from the current image first.')
        other = 'b' if np.allclose(it['down'], it['a']) else 'a'
        return self.orient(index, other, evidence)

    def fill(self):
        """Right hand takes and holds the holder; left hand puts every tool on the table into it, looking again after a miss."""
        r = fill(self.robo)
        measured = {k: v for k, v in r.items() if k not in ('ok', 'why')}
        measured['tools'] = self._tools()
        return self._out(r['ok'], r.get('why'), measured,
                         self._picture() if r.get('needs_orientation') or r.get('needs_dimensions') else None)

    def status(self):
        """Look again without touching anything in the holder: which tools still lie on the table (moves only the left arm aside)."""
        if S.get('hold_xy') is None:
            return self.survey()
        seen = relook(self.robo)
        del SNAPS[:]
        return self._out(True, None, dict(left_on_table=seen['left'], tools=self._tools()), self._picture())

    def finish(self):
        """Right hand releases the holder and backs out; both arms return to the start pose together (full clearance route by default); do not waste actions."""
        r = finish(self.robo)
        return self._out(r['ok'], None if r['ok'] else 'arms not at the start pose yet: call finish again',
                         dict(home=r['home'], route=r['route']))


_ROUTINES = {}


def routines(robo):
    """The one Routines object of this episode."""
    if 'r' not in _ROUTINES or _ROUTINES['r'].robo is not robo:
        _ROUTINES['r'] = Routines(robo)
    return _ROUTINES['r']


def holder_colour(rgb):
    """Pixels with the bright orange of the holder's rim and lit walls (the wooden table is darker and redder)."""
    import cv2
    hsv = cv2.cvtColor(np.ascontiguousarray(np.asarray(rgb)[:, :, :3]), cv2.COLOR_RGB2HSV)
    h, s, v = hsv[:, :, 0].astype(int), hsv[:, :, 1].astype(int), hsv[:, :, 2].astype(int)
    return (h >= 10) & (h <= 24) & (s >= 120) & (v >= 170)


def _prism_mask(K, E, xy, yaw, shape, radius, z0, z1):
    import cv2
    ang = math.radians(yaw) + np.arange(6) * math.pi / 3
    ring = np.c_[xy[0] + radius * np.cos(ang), xy[1] + radius * np.sin(ang)]
    pts = np.r_[np.c_[ring, np.full(6, z0)], np.c_[ring, np.full(6, z1)]]
    rc = project(K, E, pts)
    hull = cv2.convexHull(np.round(rc[:, ::-1]).astype(np.int32))
    m = np.zeros(shape, np.uint8)
    cv2.fillConvexPoly(m, hull, 1)
    return m > 0


def fit_holder_top(rgb, K, E, guess=None, z0=TABLE_Z, radius=HOLDER_OUTER_R):
    """Axis position and corner direction of the upright hexagonal holder from a view from above.

    The orange rim and walls are found by colour, the opening is filled in, and a hexagonal prism of the
    holder's declared size is fitted to that outline. Returns xy (world), yaw of one corner (0..60 deg), overlap.
    """
    import cv2
    orange = holder_colour(rgb).astype(np.uint8)
    orange = cv2.morphologyEx(orange, cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8))
    n, labels, stats, cent = cv2.connectedComponentsWithStats(orange)
    if n < 2:
        return None
    if guess is not None:
        gr, gc = project(K, E, [guess[0], guess[1], z0 + HOLDER_HEIGHT])[0]
        score = [stats[i, cv2.CC_STAT_AREA] / (1.0 + ((cent[i][0] - gc) ** 2 + (cent[i][1] - gr) ** 2) / 80.0 ** 2) for i in range(1, n)]
        i = 1 + int(np.argmax(score))
    else:
        i = 1 + int(np.argmax(stats[1:, cv2.CC_STAT_AREA]))
    if stats[i, cv2.CC_STAT_AREA] < 400:
        return None
    blob = (labels == i).astype(np.uint8)
    contours, _ = cv2.findContours(blob, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    filled = np.zeros_like(blob)
    cv2.fillPoly(filled, [cv2.convexHull(np.vstack(contours))], 1)
    filled = filled > 0
    rows, cols = np.nonzero(filled)
    r0, r1, c0, c1 = max(0, rows.min() - 30), min(filled.shape[0], rows.max() + 31), max(0, cols.min() - 30), min(filled.shape[1], cols.max() + 31)
    crop = filled[r0:r1, c0:c1]
    Kc = K.copy()
    Kc[0, 2] -= c0
    Kc[1, 2] -= r0
    start = ray_at_z(K, E, (rows.mean(), cols.mean()), z0 + HOLDER_HEIGHT)[:2]
    best = (-1.0, start, 0.0)
    for span, step, yaws in ((0.024, 0.004, np.arange(0, 60, 10.0)), (0.004, 0.001, None)):
        centre, y0 = best[1], best[2]
        for yaw in (yaws if yaws is not None else y0 + np.arange(-8, 9, 2.0)):
            for dx in np.arange(-span, span + 1e-9, step):
                for dy in np.arange(-span, span + 1e-9, step):
                    xy = centre + np.array([dx, dy])
                    m = _prism_mask(Kc, E, xy, yaw, crop.shape, radius, z0, z0 + HOLDER_HEIGHT)
                    iou = float((m & crop).sum()) / max(1.0, float((m | crop).sum()))
                    if iou > best[0]:
                        best = (iou, xy, float(yaw))
    return dict(xy=best[1], yaw=best[2] % 60.0, iou=best[0], area=int(stats[i, cv2.CC_STAT_AREA]))
